import type { RegionKey } from '../types';
import { type MusicSlot, setNowPlaying } from './nowPlaying';

/**
 * Plays the recorded per-region soundtrack listed in public/music/manifest.json (generated by
 * scripts/gen-music.mjs) and crossfades as the globe turns from one region to another.
 *
 * Same interface as the procedural MusicEngine, which stays as the fallback when no tracks have
 * been generated yet. Volume runs through Web Audio gain nodes, because iOS ignores
 * HTMLMediaElement.volume.
 *
 * - Loops without a gap. Each region's takes play as a playlist. Once a take's ending has died
 *   away (its manifest `crossfadeAt`, at the latest when its baked fade-out begins), the next take
 *   (or the same one again) starts on a second element and the two overlap, instead of the old
 *   fade to silence and restart.
 * - A small pool of <audio> elements is created and unlocked inside the first click (iOS only lets
 *   an element play from a user gesture) and shared between regions. A region you leave keeps its
 *   element, and resumes where it left off, until the pool needs it; then it remembers its
 *   position and lets the element (and its download) go.
 * - A take that fails to load is skipped; a region with no playable take falls back to the
 *   open-sea score and is retried a minute later. A dropped connection mid-track is retried once.
 * - A suspended or interrupted AudioContext (iOS after a call, autoplay without a gesture) is
 *   resumed on the next tap or key press.
 * - Media Session: the OS media controls show the track and can pause and resume it.
 */

export interface MusicTrack {
  file: string;
  title: string;
  duration: number;
  /** Seconds of fade-out baked into the end of the file. */
  fadeOut?: number;
  /**
   * When to start the next take (s from the start): where this take's ending has died away,
   * which can be several seconds before the fade-out. Default: `fadeOut` before the end.
   */
  crossfadeAt?: number;
}
export interface MusicManifest {
  generated: string | null;
  regions: Partial<Record<MusicSlot, MusicTrack[]>>;
}

type Slot = MusicSlot;

/** One <audio> element, wired into Web Audio once and lent to a channel at a time. */
interface Deck {
  el: HTMLAudioElement;
  node: MediaElementAudioSourceNode;
  ch: Channel | null;
  take: number;
}

interface Channel {
  slot: Slot;
  tracks: MusicTrack[];
  gain: GainNode;
  /** The take playing, and where to resume it when the channel has had to give its deck back. */
  index: number;
  pos: number;
  main: Deck | null;
  /** The following take, loading ahead of the loop crossfade. */
  next: Deck | null;
  /** The previous take, playing out its fade under `main`. */
  tail: Deck | null;
  /** Failed loads per take; a take is skipped at 2. */
  errors: number[];
  /** performance.now() until which the region counts as unplayable (every take failed). */
  deadUntil: number;
  pauseTimer?: number;
}

const BASE = `${import.meta.env.BASE_URL}music/`;
const FADE = 3.5; // seconds for a region crossfade
const SETTLE = 900; // ms a region must stay put before the music follows (region detection can flicker)
const OCEAN_SETTLE = 6000; // ms over open sea before switching to the sea track
const LEVEL = 0.7;
const POOL = 4; // two regions crossfading, each possibly mid-loop
const LOOP_FADE = 4; // default for manifests without `fadeOut`
const PREPARE = 12; // s before the loop crossfade to start loading the next take
const RETRY_MS = 1500;
const DEAD_MS = 60_000;

export async function loadManifest(): Promise<MusicManifest | null> {
  try {
    const res = await fetch(`${BASE}manifest.json`, { cache: 'no-cache' });
    if (!res.ok) return null;
    const m = (await res.json()) as MusicManifest;
    return Object.values(m.regions ?? {}).some((t) => t?.length) ? m : null;
  } catch {
    return null;
  }
}

function ramp(p: AudioParam, ctx: AudioContext, to: number, secs: number) {
  const now = ctx.currentTime;
  p.cancelScheduledValues(now);
  p.setValueAtTime(p.value, now);
  p.linearRampToValueAtTime(to, now + secs);
}

export class TrackPlayer {
  private ctx: AudioContext | null = null;
  private master!: GainNode;
  private decks: Deck[] = [];
  private channels = new Map<Slot, Channel>();
  private current: Channel | null = null;
  private enabled = false;
  private pending: number | undefined;
  private region: RegionKey | null = null;
  private holdUntil = 0;
  private unlockArmed = false;
  /** OS media controls asked to play (true) or pause (false); the app routes this through its store. */
  onRemote: ((on: boolean) => void) | null = null;

  constructor(private manifest: MusicManifest) {}

  private init() {
    if (this.ctx) return;
    const ctx = new AudioContext({ latencyHint: 'playback' });
    this.ctx = ctx;
    this.master = ctx.createGain();
    this.master.gain.value = 0;
    this.master.connect(ctx.destination);
    for (let i = 0; i < POOL; i++) this.newDeck();
    ctx.addEventListener('statechange', () => {
      if (this.enabled && ctx.state !== 'running' && ctx.state !== 'closed') this.armUnlock();
    });
    // iOS: let the music play with the ring/silent switch on, as a music app would, once asked for.
    const session = (navigator as Navigator & { audioSession?: { type: string } }).audioSession;
    if (session) session.type = 'playback';
    if ('mediaSession' in navigator) {
      const set = (action: MediaSessionAction, fn: () => void) => {
        try {
          navigator.mediaSession.setActionHandler(action, fn);
        } catch {
          /* action not supported here */
        }
      };
      set('play', () => this.remote(true));
      set('pause', () => this.remote(false));
      set('stop', () => this.remote(false));
    }
  }

  private remote(on: boolean) {
    if (this.onRemote) this.onRemote(on);
    else this.setEnabled(on, this.region);
  }

  private newDeck(): Deck {
    const el = new Audio();
    el.preload = 'auto';
    el.crossOrigin = 'anonymous';
    const d: Deck = { el, node: this.ctx!.createMediaElementSource(el), ch: null, take: 0 };
    el.addEventListener('timeupdate', () => this.onTime(d));
    el.addEventListener('ended', () => this.onEnded(d));
    el.addEventListener('error', () => this.onError(d));
    this.decks.push(d);
    return d;
  }

  /**
   * Resume the AudioContext and unlock the idle elements. Inside a user gesture this is what lets
   * iOS play them later; outside one it is harmless.
   */
  private unlock() {
    const ctx = this.ctx;
    if (!ctx) return;
    if (ctx.state !== 'running') void ctx.resume().catch(() => {});
    for (const d of this.decks) if (!d.ch) d.el.load();
    window.setTimeout(() => {
      if (this.enabled && ctx.state !== 'running') this.armUnlock();
    }, 600);
  }

  /** Try again on the next tap or key press (autoplay blocked, or iOS suspended the context). */
  private armUnlock() {
    if (this.unlockArmed) return;
    this.unlockArmed = true;
    const types = ['pointerup', 'touchend', 'click', 'keydown'] as const;
    const go = () => {
      this.unlockArmed = false;
      for (const t of types) window.removeEventListener(t, go, true);
      if (!this.enabled) return;
      this.unlock();
      if (this.current) this.start(this.current);
    };
    for (const t of types) window.addEventListener(t, go, true);
  }

  /** The slot to play for a region: its own tracks, else the open-sea score, else whatever plays now. */
  private slotFor(region: RegionKey | null): Slot | null {
    const ok = (s: Slot) => !!this.manifest.regions[s]?.length && (this.channels.get(s)?.deadUntil ?? 0) <= performance.now();
    if (region && ok(region)) return region;
    if (ok('ocean')) return 'ocean';
    if (this.current && ok(this.current.slot)) return this.current.slot;
    return (Object.keys(this.manifest.regions) as Slot[]).find(ok) ?? null;
  }

  private channel(slot: Slot): Channel {
    let ch = this.channels.get(slot);
    if (ch) return ch;
    const tracks = this.manifest.regions[slot]!;
    const gain = this.ctx!.createGain();
    gain.gain.value = 0;
    gain.connect(this.master);
    // Different visitors hear different takes first.
    ch = { slot, tracks, gain, index: Math.floor(Math.random() * tracks.length), pos: 0, main: null, next: null, tail: null, errors: [], deadUntil: 0 };
    this.channels.set(slot, ch);
    return ch;
  }

  /** A free deck: an idle one, else one taken back from a region that is not sounding, else a new one. */
  private acquire(): Deck {
    const free = this.decks.find((d) => !d.ch);
    if (free) return free;
    const silent = (c: Channel) => c !== this.current && ![c.main, c.tail].some((d) => d && !d.el.paused);
    const victim = this.decks.find((d) => d.ch && silent(d.ch))?.ch;
    if (victim) {
      this.release(victim);
      return this.decks.find((d) => !d.ch)!;
    }
    return this.newDeck();
  }

  private load(d: Deck, ch: Channel, take: number, at = 0) {
    d.ch = ch;
    d.take = take;
    d.node.disconnect();
    d.node.connect(ch.gain);
    d.el.preload = 'auto';
    d.el.src = BASE + ch.tracks[take].file;
    // Before metadata this sets the start position, which is how a region resumes.
    if (at > 0) d.el.currentTime = at;
  }

  private free(d: Deck | null) {
    if (!d) return;
    d.ch = null;
    d.el.pause();
    d.el.removeAttribute('src');
    d.el.load(); // drops the buffered audio and stops any download
    d.node.disconnect();
  }

  /** Give a silent region's decks back, remembering where its take was. */
  private release(ch: Channel) {
    if (ch.main) {
      ch.index = ch.main.take;
      ch.pos = ch.main.el.ended ? 0 : ch.main.el.currentTime;
    }
    this.free(ch.main);
    this.free(ch.next);
    this.free(ch.tail);
    ch.main = ch.next = ch.tail = null;
  }

  private play(d: Deck) {
    void d.el.play().catch((e: unknown) => {
      if ((e as DOMException)?.name === 'NotAllowedError') this.armUnlock();
    });
  }

  /** Start or resume a channel's take (and the end of the previous take, if it is mid-crossfade). */
  private start(ch: Channel) {
    window.clearTimeout(ch.pauseTimer);
    if (!ch.main) {
      if (ch.deadUntil && ch.deadUntil <= performance.now()) {
        ch.errors = [];
        ch.deadUntil = 0;
      }
      const take = ch.errors[ch.index] >= 2 ? this.nextTake(ch, ch.index) : ch.index;
      if (take < 0) return;
      if (take !== ch.index) ch.pos = 0;
      ch.main = this.acquire();
      this.load(ch.main, ch, take, ch.pos);
    }
    this.play(ch.main);
    if (ch.tail && !ch.tail.el.ended) this.play(ch.tail);
  }

  private pause(ch: Channel) {
    ch.main?.el.pause();
    ch.tail?.el.pause();
    // Stop buffering ahead for a region we have left; the next take is loaded again when needed.
    if (ch.main) ch.main.el.preload = 'metadata';
    this.free(ch.next);
    ch.next = null;
  }

  /** The take after `from` that has not failed, cycling; the same take when it is the only one. */
  private nextTake(ch: Channel, from: number): number {
    const n = ch.tracks.length;
    for (let i = 1; i <= n; i++) {
      const k = (from + i) % n;
      if ((ch.errors[k] ?? 0) < 2) return k;
    }
    return -1;
  }

  private onTime(d: Deck) {
    const ch = d.ch;
    if (!ch || d !== ch.main || ch !== this.current || !this.enabled || d.el.paused) return;
    const track = ch.tracks[d.take];
    const dur = Number.isFinite(d.el.duration) ? d.el.duration : track.duration;
    const left = Math.min(track.crossfadeAt ?? dur, dur - (track.fadeOut ?? LOOP_FADE)) - d.el.currentTime;
    if (left <= PREPARE && !ch.next) {
      const take = this.nextTake(ch, d.take);
      if (take >= 0) {
        ch.next = this.acquire();
        this.load(ch.next, ch, take);
      }
    }
    if (left <= 0) this.advance(ch);
  }

  /** Loop crossfade: the next take starts while the current one plays out its baked fade. */
  private advance(ch: Channel) {
    const from = ch.main?.take ?? ch.index;
    let incoming = ch.next;
    ch.next = null;
    if (!incoming) {
      const take = this.nextTake(ch, from);
      if (take < 0) return;
      incoming = this.acquire();
      this.load(incoming, ch, take);
    }
    this.free(ch.tail);
    ch.tail = ch.main && !ch.main.el.ended ? ch.main : null;
    if (ch.main && !ch.tail) this.free(ch.main);
    ch.main = incoming;
    ch.index = incoming.take;
    ch.pos = 0;
    this.play(incoming);
    this.announce();
  }

  private onEnded(d: Deck) {
    const ch = d.ch;
    if (!ch) return;
    if (d === ch.tail) {
      this.free(d);
      ch.tail = null;
    } else if (d === ch.main) {
      // Ended without a crossfade (it was paused or seeked past the point): go on, or rewind.
      if (ch === this.current && this.enabled) this.advance(ch);
      else {
        ch.index = Math.max(0, this.nextTake(ch, d.take));
        ch.pos = 0;
        this.free(d);
        ch.main = null;
      }
    }
  }

  private onError(d: Deck) {
    const ch = d.ch;
    if (!ch) return;
    const take = d.take;
    const code = d.el.error?.code;
    // A dropped connection gets one retry from where it stopped; a missing or broken file none.
    ch.errors[take] = (ch.errors[take] ?? 0) + (code === MediaError.MEDIA_ERR_NETWORK ? 1 : 2);
    console.warn(`music: ${ch.tracks[take].file} failed to load (MediaError ${code ?? '?'})`);
    if (d === ch.tail || d === ch.next) {
      this.free(d);
      if (d === ch.tail) ch.tail = null;
      else ch.next = null;
      return;
    }
    if (d !== ch.main) return;
    const live = () => ch === this.current && this.enabled;
    if (ch.errors[take] < 2) {
      const at = d.el.currentTime;
      window.setTimeout(() => {
        if (ch.main !== d) return;
        this.load(d, ch, take, at);
        if (live()) this.play(d);
      }, RETRY_MS);
      return;
    }
    this.free(d);
    ch.main = null;
    const alt = this.nextTake(ch, take);
    if (alt >= 0) {
      ch.index = alt;
      ch.pos = 0;
      if (live()) this.start(ch);
      this.announce();
      return;
    }
    // Nothing in this region plays: fall back (to the open-sea score) and retry it later.
    ch.deadUntil = performance.now() + DEAD_MS;
    if (ch === this.current) this.switchTo(this.slotFor(this.region), 1.5);
  }

  private announce() {
    const c = this.current;
    const on = this.enabled && !!c && c.deadUntil <= performance.now();
    setNowPlaying(on ? c.slot : null);
    if (!('mediaSession' in navigator)) return;
    const take = c?.main?.take ?? c?.index;
    const t = c && take !== undefined ? c.tracks[take] : null;
    if (on && t && typeof MediaMetadata !== 'undefined')
      navigator.mediaSession.metadata = new MediaMetadata({
        title: t.title,
        artist: 'Orbis · 寰宇时序',
        artwork: [{ src: new URL(`${import.meta.env.BASE_URL}favicon.svg`, location.href).href, sizes: 'any', type: 'image/svg+xml' }],
      });
    navigator.mediaSession.playbackState = on ? 'playing' : 'paused';
  }

  private switchTo(slot: Slot | null, fade = FADE) {
    if (!this.ctx) return;
    const prev = this.current;
    if (!slot) {
      // Nothing playable at all.
      if (prev) ramp(prev.gain.gain, this.ctx, 0, 0.5);
      this.current = null;
      this.announce();
      return;
    }
    if (prev?.slot === slot) return;
    if (prev) {
      ramp(prev.gain.gain, this.ctx, 0, fade);
      // Pause once silent; returning to the region later resumes where it left off.
      window.clearTimeout(prev.pauseTimer);
      prev.pauseTimer = window.setTimeout(() => this.current !== prev && this.pause(prev), fade * 1000 + 100);
    }
    const next = this.channel(slot);
    this.current = next;
    ramp(next.gain.gain, this.ctx, 1, fade);
    this.start(next);
    this.announce();
  }

  /**
   * Keep the music where it is for `ms` from now (e.g. while the intro swings the camera round), so
   * the regions it sweeps over on the way do not each start a track. Calling it again extends or
   * shortens the hold; a switch already scheduled waits for the latest hold.
   */
  holdFor(ms: number) {
    this.holdUntil = performance.now() + ms;
  }

  /** Must be called from a user gesture the first time (autoplay rules). */
  setEnabled(on: boolean, region: RegionKey | null) {
    this.enabled = on;
    this.region = region;
    if (on) {
      this.init();
      this.unlock();
      ramp(this.master.gain, this.ctx!, LEVEL, 1.2);
      const want = this.slotFor(region);
      // The camera may have moved on while the music was off: go straight to where it is now.
      if (this.current && want && want !== this.current.slot) this.switchTo(want, 1.5);
      else if (this.current) this.start(this.current);
      else this.follow();
      this.announce();
    } else if (this.ctx) {
      window.clearTimeout(this.pending);
      ramp(this.master.gain, this.ctx, 0, 0.8);
      window.setTimeout(() => {
        if (!this.enabled) for (const c of this.channels.values()) this.pause(c);
      }, 900);
      this.announce();
    }
  }

  setRegion(region: RegionKey | null) {
    this.region = region;
    if (this.enabled) this.follow();
  }

  /**
   * Schedule a switch to the region now under the camera. A real region must hold for SETTLE ms;
   * open sea for OCEAN_SETTLE ms, because fly-tos routinely pass over water; nothing switches
   * during a hold. The target is re-read when the timer fires, so only the latest region counts.
   */
  private follow() {
    window.clearTimeout(this.pending);
    if (this.current && this.slotFor(this.region) === this.current.slot) return;
    const hold = Math.max(0, this.holdUntil - performance.now());
    // Nothing playing yet: a real region starts at once, open sea only after a longer wait.
    const settle = !this.current ? (this.region ? 0 : OCEAN_SETTLE * 1.5) : this.region ? SETTLE : OCEAN_SETTLE;
    this.pending = window.setTimeout(() => {
      if (!this.enabled) return;
      // The hold was extended meanwhile (the camera is still landing): wait it out.
      if (this.holdUntil > performance.now()) return this.follow();
      this.switchTo(this.slotFor(this.region), this.current ? FADE : 1.5);
    }, Math.max(hold, settle));
  }
}
